WITH flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM transactions), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT id, account_id, amount, is_flagged, is_new_session, burst_id FROM sessions_transactions ORDER BY burst_id DESC NULLS FIRST, id DESC;
